<template>
  <ClientOnly>
    <div
      ref="containerRef"
      class="grid size-full grid-cols-3 grid-rows-5 gap-1"
    >
      <div
        v-for="(item, index) in items"
        :key="index"
        class="text-kv-brown-200 dark:text-kv-brown-900 *:size-full"
        v-html="item"
      />
    </div>
  </ClientOnly>
</template>

<script setup>
import { gsap } from "gsap";
import { Flip } from "gsap/Flip";

const containerRef = ref(null);
let ctx;

const shuffle = () => {
  if (!containerRef.value) return;

  const items = gsap.utils.toArray(containerRef.value.children);

  const state = Flip.getState(items);

  const fromIndex = gsap.utils.random(0, items.length - 1, 1);
  let toIndex = gsap.utils.random(0, items.length - 1, 1);
  while (toIndex === fromIndex) {
    toIndex = gsap.utils.random(0, items.length - 1, 1);
  }

  const itemToMove = items[fromIndex];
  const targetItem = items[toIndex];
  containerRef.value.insertBefore(itemToMove, targetItem);

  Flip.from(state, {
    duration: 1,
    ease: "power1.inOut",
    onComplete: () => {
      gsap.delayedCall(gsap.utils.random(0.5, 2), shuffle);
    },
  });
};

onMounted(() => {
  gsap.registerPlugin(Flip);

  ctx = gsap.context(() => {
    gsap.delayedCall(1, shuffle);
  }, containerRef.value);
});

onUnmounted(() => {
  if (ctx) {
    ctx.revert();
  }
});
